<script setup>import{useForm}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';import Pagination from'../../Components/Pagination.vue';defineProps({inquiries:Object});const save=i=>useForm({status:i.status,admin_notes:i.admin_notes||''}).patch(`/admin/inquiries/${i.id}`,{preserveScroll:true});</script><template><AdminLayout><p class="section-kicker">Customers</p><h1 class="section-title">Service requests</h1><div class="mt-6 grid gap-4"><div v-for="i in inquiries.data" :key="i.id" class="card p-5"><div class="flex flex-wrap justify-between gap-3"><div><b>{{i.name}}</b><p class="text-sm text-slate-500">{{i.service?.name}} · {{i.phone}} · {{i.email}}</p></div><span class="status bg-slate-100">{{i.status}}</span></div><p class="mt-3 text-sm">{{i.message}}</p><div class="mt-4 flex gap-2"><select :value="i.status" class="input max-w-xs" @change="useForm({status:$event.target.value,admin_notes:i.admin_notes||''}).patch(`/admin/inquiries/${i.id}`)"><option v-for="s in ['new','contacted','scheduled','completed','closed']" :key="s">{{s}}</option></select></div></div></div><Pagination :links="inquiries.links"/></AdminLayout></template>
